rss.channel:
spnews · 体育日报
{{ site_url }}/
每日自动聚合 MLB、NFL、F1、足球、NBA 核心体育新闻中文摘要
zh-CN
{{ build_date }}

{% for report in reports %}


  体育日报 {{ report.report_date }}
  {{ site_url }}/reports/{{ report.report_date }}/
  {{ site_url }}/reports/{{ report.report_date }}/
  {{ report.pub_rfc822 }}

    {% if report.overview_html %}
    <h2>今日要点</h2>
    <ul>
      {% for b in report.overview_html %}<li>{{ b | safe }}</li>{% endfor %}
    </ul>
    {% endif %}
    {% for sec in report.sections %}
    <h2>{{ sec.sport_name }}</h2>
      {% for ev in sec.events %}
      <h3>{% if ev.importance == 'high' %}[重大] {% endif %}{{ ev.title }}</h3>
      {{ ev.summary_html | safe }}
      {% if ev.sources %}
      <p><small>来源：{% for s in ev.sources %}<a href="{{ s.url }}">{{ s.source_name }}</a>{% if not loop.last %} · {% endif %}{% endfor %}</small></p>
      {% endif %}
      {% endfor %}
    {% endfor %}


{% endfor %}
